<?php

declare(strict_types=1);
namespace OCA\MaintenanceTracker\Db;
use OCP\AppFramework\Db\Entity; use OCP\DB\Types;
/** @method int getWorkspaceId() @method void setWorkspaceId(int $v) @method int getActivityId() @method void setActivityId(int $v) @method string getUuid() @method void setUuid(string $v) @method int getPosition() @method void setPosition(int $v) @method ?int getDefinitionId() @method void setDefinitionId(?int $v) @method ?string getDefinitionUuid() @method void setDefinitionUuid(?string $v) @method ?int getComponentId() @method void setComponentId(?int $v) @method ?string getComponentUuid() @method void setComponentUuid(?string $v) @method ?string getComponentName() @method void setComponentName(?string $v) @method string getTitle() @method void setTitle(string $v) @method string getKind() @method void setKind(string $v) @method ?string getNotes() @method void setNotes(?string $v) */
final class ActivityItem extends Entity { protected int $workspaceId=0; protected int $activityId=0; protected string $uuid=''; protected int $position=0; protected ?int $definitionId=null; protected ?string $definitionUuid=null; protected ?int $componentId=null; protected ?string $componentUuid=null; protected ?string $componentName=null; protected string $title=''; protected string $kind=''; protected ?string $notes=null; public function __construct(){foreach(['workspaceId','activityId','position','definitionId','componentId'] as $f)$this->addType($f,Types::BIGINT);foreach(['uuid','definitionUuid','componentUuid','componentName','title','kind','notes'] as $f)$this->addType($f,Types::STRING);} }
